const crypto = require('crypto');

// Example implementation using AES-256-GCM
function encryptDataGCM(key, data) {
    if (![16, 24, 32].includes(key.length)) {
        throw new Error('Key length must be 16, 24, or 32 bytes');
    }

    const keyLength = key.length;
    const aesKey = key.slice(0, keyLength);

    // Generate random IV and nonce for GCM mode
    const iv = crypto.randomBytes(12); // 96 bits IV (GCM mode requires 12 bytes)
    const cipher = crypto.createCipheriv(`aes-${keyLength * 8}-gcm`, aesKey, iv);

    // Encrypt the data with additional authenticated data (AAD)
    const aad = Buffer.from('authenticated_data'); // Optional AAD
    const encryptedData = Buffer.concat([cipher.update(data, undefined, 'utf8'), cipher.final()]);

    // Get the authentication tag
    const authTag = cipher.getAuthTag();

    return {
        encryptedData,
        iv,
        aesKey,
        authTag
    };
}
